	wire rst;				// KEY0 apertado = reset
	wire button;			// KEY1 apertado = botão do portão
	wire clk_1ms;			// clock de 1 ms (FSM e detector de borda)
	wire clk_1s;			// clock de 1 s (temporizador e simulador do portão)
	wire [2:0] timer_count;	// segundos contados com o portão aberto

	// As teclas da DE10-Lite são ativas em nível baixo (apertada = 0),
	// então invertemos com ~ (NOT bit a bit).
	// Obs.: nas aulas 5 e 6 estava "-KEY[0]". O "-" é negação aritmética e,
	// em 1 bit, -1 = 1 e -0 = 0, ou seja, NÃO inverte nada.
	assign rst    = ~KEY[0];
	assign button = ~KEY[1];

//=======================================================
//  Structural coding
//=======================================================

	// 50 MHz -> 1 ms: inverte a cada 25.000 ciclos (período de 50.000 ciclos)
	clk_div #(.N(25000)) u_div_1ms (
		.rst(rst),
		.clk_in(MAX10_CLK1_50),
		.clk_out(clk_1ms)
	);

	// 50 MHz -> 1 s: inverte a cada 25.000.000 ciclos
	clk_div #(.N(25000000)) u_div_1s (
		.rst(rst),
		.clk_in(MAX10_CLK1_50),
		.clk_out(clk_1s)
	);

	// Portão: LEDR mostra a posição, KEY1 abre/fecha
	portao u_portao (
		.rst(rst),
		.clk_1ms(clk_1ms),
		.clk_1s(clk_1s),
		.button(button),
		.led_bar(LEDR),
		.timer_count(timer_count),
		.motor_power(),
		.motor_direction(),
		.gate_open()
	);

	// HEX0 mostra os segundos contados com o portão aberto (0 a 5)
	bin7seg u_hex0 (
		.bin({1'b0, timer_count}),
		.hex(HEX0)
	);

	// Displays não usados: apagados (segmentos ativos em nível baixo)
	assign HEX1 = 8'hFF;
	assign HEX2 = 8'hFF;
